<?php use App\Services\AdmissionService as A; $id = (int)$a['id']; $st = $a['status']; ?>
<div class="row g-3">
 <div class="col-lg-7"><div class="card-s"><div class="d-flex justify-content-between"><h2 class="h5"><?= e($a['applicant_name']) ?></h2><span class="badge text-bg-info align-self-start"><?= e(A::STATUSES[$st] ?? $st) ?></span></div>
  <dl class="row small mb-0"><dt class="col-4">الصف</dt><dd class="col-8"><?= e($a['grade_name'] ?? '—') ?></dd><dt class="col-4">الميلاد</dt><dd class="col-8"><?= e($a['birth_date'] ?? '—') ?></dd><dt class="col-4">الجنس</dt><dd class="col-8"><?= ['male' => 'ذكر', 'female' => 'أنثى'][$a['gender'] ?? ''] ?? '—' ?></dd>
  <dt class="col-4">الهوية</dt><dd class="col-8" dir="ltr"><?= e($a['national_id'] ?: '—') ?></dd><dt class="col-4">ولي الأمر</dt><dd class="col-8"><?= e($a['guardian_name'] ?? '—') ?> <span dir="ltr"><?= e($a['guardian_phone'] ?? '') ?></span></dd>
  <dt class="col-4">المدرسة السابقة</dt><dd class="col-8"><?= e($a['previous_school'] ?? '—') ?></dd><dt class="col-4">العنوان</dt><dd class="col-8"><?= e($a['address'] ?? '—') ?></dd><dt class="col-4">ملاحظات</dt><dd class="col-8"><?= e($a['notes'] ?? '—') ?></dd>
  <?php if ($a['decision_note']): ?><dt class="col-4">ملاحظة القرار</dt><dd class="col-8"><?= e($a['decision_note']) ?> <small class="text-muted">(<?= e($a['decided_name'] ?? '') ?>)</small></dd><?php endif; ?></dl>
  <?php if ($st !== 'enrolled'): ?><a class="btn btn-sm btn-outline-primary mt-2" href="<?= url("school/admissions/$id/edit") ?>"><i class="bi bi-pencil"></i> تعديل</a><?php endif; ?></div>
  <div class="card-s mt-3"><h2 class="h6">الوثائق</h2><?php if (!$a['documents']): ?><div class="text-muted small">لا وثائق.</div><?php endif; ?>
  <?php foreach ($a['documents'] as $d): ?><div class="d-flex justify-content-between border-bottom py-1"><a href="<?= url('files/' . (int)$d['file_id']) ?>"><?= e($d['title']) ?> <small class="text-muted"><?= e($d['original_name']) ?></small></a><button class="btn btn-sm btn-outline-danger" data-api="<?= url("api/v1/school/admissions/$id/documents/" . (int)$d['id']) ?>" data-method="DELETE" data-confirm="حذف الوثيقة؟"><i class="bi bi-trash"></i></button></div><?php endforeach; ?>
  <?php if ($st !== 'enrolled'): ?><form class="row g-2 mt-2" method="post" action="<?= url("api/v1/school/admissions/$id/documents") ?>" data-ajax data-multipart data-reload novalidate><?= csrf_field() ?><div class="col-sm-4"><input class="form-control form-control-sm" name="title" placeholder="العنوان" aria-label="العنوان"></div><div class="col-sm-5"><input class="form-control form-control-sm" type="file" name="file" aria-label="الملف"></div><div class="col-sm-3"><button class="btn btn-sm btn-outline-primary w-100">إرفاق</button></div></form><?php endif; ?></div></div>
 <div class="col-lg-5"><div class="card-s"><h2 class="h6">إجراءات</h2>
  <?php if ($st === 'new'): ?><button class="btn btn-primary btn-sm" data-api="<?= url("api/v1/school/admissions/$id/status") ?>" data-body='{"status":"review"}' data-reload>بدء المراجعة</button><?php endif; ?>
  <?php if (in_array($st, ['new', 'review'], true)): ?><button class="btn btn-success btn-sm" data-api="<?= url("api/v1/school/admissions/$id/status") ?>" data-body='{"status":"accepted"}' data-reload>قبول</button>
   <button class="btn btn-outline-danger btn-sm" data-api="<?= url("api/v1/school/admissions/$id/status") ?>" data-body='{"status":"rejected"}' data-prompt="سبب الرفض (مطلوب)" data-prompt-field="note" data-reload>رفض</button><?php endif; ?>
  <?php if ($st === 'accepted'): ?><form class="mt-2" method="post" action="<?= url("api/v1/school/admissions/$id/enroll") ?>" data-ajax data-redirect novalidate><?= csrf_field() ?><label class="form-label" for="sec">تسجيله في شعبة</label><select class="form-select mb-2" id="sec" name="section_id" required><option value="">—</option><?php foreach ($sections as $s): ?><option value="<?= (int)$s['id'] ?>"><?= e($s['grade_name'] . ' / ' . $s['name']) ?></option><?php endforeach; ?></select><button class="btn btn-primary btn-sm">تسجيل كطالب</button></form><?php endif; ?>
  <?php if ($st === 'enrolled'): ?><div class="text-success small"><i class="bi bi-check-circle"></i> مُسجَّل كطالب.</div><?php endif; ?>
  <?php if ($st === 'rejected'): ?><div class="text-muted small">الطلب مرفوض.</div><?php endif; ?></div></div>
</div>
